import * as React from 'react'
import { cva } from 'class-variance-authority'
import { cn } from '@/lib/utils'

const inputVariants = cva(
  cn(
    'wj-focus-ring w-full rounded-full pl-9 pr-8 text-sm',
    'bg-[var(--color-surface-light)] dark:bg-[var(--color-surface-dark)]',
    'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
    'text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)]',
    'placeholder:text-[var(--color-text-muted-light)] dark:placeholder:text-[var(--color-text-muted-dark)]',
  ),
  {
    variants: {
      size: {
        sm: 'h-9',
        md: 'h-10',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

// Floating-pill chrome for `variant="frosted"` -- the recipe Chip Away's
// MobileFloatingSearch hand-rolled: frosted surface, border, and a
// focus-within outline standing in for the (removed) input border.
const FROSTED_ROOT =
  'flex items-center gap-2 h-12 px-4 rounded-full backdrop-blur-[16px] shadow-lg ' +
  'bg-[color-mix(in_srgb,var(--color-surface-light)_80%,transparent)] ' +
  'dark:bg-[color-mix(in_srgb,var(--color-surface-dark)_80%,transparent)] ' +
  'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)] ' +
  'focus-within:outline focus-within:outline-2 focus-within:outline-offset-2 ' +
  'focus-within:outline-[var(--color-text-primary-light)] dark:focus-within:outline-[var(--color-text-primary-dark)]'

const FROSTED_INPUT =
  'flex-1 min-w-0 bg-transparent text-sm focus:outline-none ' +
  'text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)] ' +
  'placeholder:text-[var(--color-text-muted-light)] dark:placeholder:text-[var(--color-text-muted-dark)]'

export interface SearchFieldProps {
  value: string
  onChange: (value: string) => void
  /** Accessible name for the input -- the placeholder is not a label. */
  label: string
  /** Accessible name AND hover title for the icon-only clear button. */
  clearLabel: string
  placeholder?: string
  /** False takes the field (and its clear button) out of the tab order while
   * a wrapper keeps it mounted but visually collapsed -- a zero-width input
   * still catches Tab, and a focus ring on an invisible field reads as the
   * focus having vanished. Pair with `HeaderStandIn`'s `shown`. */
  tabbable?: boolean
  /** `md` (h-10) matches the DS control baseline; `sm` (h-9) sits flush in
   * denser chrome (a 64px header row, a sidebar rail). Applies only to
   * `variant="solid"` -- `frosted` is always `h-12`. */
  size?: 'sm' | 'md'
  /**
   * `solid` (default) is the bordered pill on a surface, with the magnifier
   * and clear button absolutely positioned inside a bordered text input.
   * `frosted` is the floating blurred pill for a bar over scrolling content
   * (Chip Away's mobile floating search): the chrome moves to the root, the
   * input goes transparent and borderless, and the magnifier (18px) and clear
   * button (16px, vs 16px/14px in solid) render as row children instead of
   * overlaying the input.
   */
  variant?: 'solid' | 'frosted'
  autoFocus?: boolean
  className?: string
  /** Inline styles for the root element. */
  style?: React.CSSProperties
}

/**
 * Search pill: a rounded-full text input with a leading magnifier and a
 * trailing clear button that appears once there is anything to clear.
 * Controlled and i18n-agnostic -- pass translated `label`, `clearLabel` and
 * `placeholder`. Inline SVG glyphs so the design system stays icon-free
 * (apps own that decision).
 */
export const SearchField = React.forwardRef<HTMLDivElement, SearchFieldProps>(
  (
    {
      value,
      onChange,
      label,
      clearLabel,
      placeholder,
      tabbable = true,
      size,
      variant = 'solid',
      autoFocus,
      className,
      style,
    },
    ref,
  ) => {
    const tabIndex = tabbable ? undefined : -1
    const frosted = variant === 'frosted'
    return (
      <div
        ref={ref}
        className={cn(frosted ? FROSTED_ROOT : 'relative', className)}
        style={style}
      >
        <svg
          className={
            frosted
              ? 'shrink-0 w-[18px] h-[18px] text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]'
              : 'absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 pointer-events-none text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]'
          }
          viewBox="0 0 16 16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          aria-hidden
        >
          <circle cx="7" cy="7" r="4.5" />
          <path d="M10.5 10.5L14 14" />
        </svg>
        <input
          type="text"
          value={value}
          autoFocus={autoFocus}
          tabIndex={tabIndex}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          aria-label={label}
          className={frosted ? FROSTED_INPUT : inputVariants({ size })}
        />
        {value && (
          <button
            type="button"
            onClick={() => onChange('')}
            aria-label={clearLabel}
            title={clearLabel}
            tabIndex={tabIndex}
            className={
              frosted
                ? 'wj-focus-ring shrink-0 rounded-full p-1 text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)] hover:text-[var(--color-text-primary-light)] dark:hover:text-[var(--color-text-primary-dark)]'
                : 'wj-focus-ring absolute right-2 top-1/2 -translate-y-1/2 rounded-full p-1 text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)] hover:text-[var(--color-text-primary-light)] dark:hover:text-[var(--color-text-primary-dark)]'
            }
          >
            <svg
              className={frosted ? 'w-4 h-4' : 'w-3.5 h-3.5'}
              viewBox="0 0 14 14"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              aria-hidden
            >
              <path d="M3 3l8 8M11 3l-8 8" />
            </svg>
          </button>
        )}
      </div>
    )
  },
)
SearchField.displayName = 'SearchField'
